def find_overlaps(bookings: list[Booking]) -> list[tuple[str, str]]:
    """Return every clashing pair as (id_a, id_b) with id_a < id_b, sorted.

    Two bookings clash when they are in the same room and their half-open
    intervals intersect. A booking fully inside a longer one clashes with it;
    a booking that ends exactly when another starts does not.
    """
    pairs: list[tuple[str, str]] = []

    # Group bookings by room
    rooms: dict[str, list[Booking]] = {}
    for booking in bookings:
        if booking.room not in rooms:
            rooms[booking.room] = []
        rooms[booking.room].append(booking)

    # For each room, find overlaps using sweep-line algorithm
    for room_bookings in rooms.values():
        # Sort by start time for sweep-line
        room_bookings.sort(key=lambda b: b.start)

        # Check each booking against subsequent ones; stop when no more overlaps possible
        for i in range(len(room_bookings)):
            a = room_bookings[i]
            for j in range(i + 1, len(room_bookings)):
                b = room_bookings[j]
                # Since sorted by start, if b starts after a ends, no more overlaps
                if b.start >= a.end:
                    break
                # Both in same room and intervals overlap
                pairs.append((a.id, b.id) if a.id < b.id else (b.id, a.id))

    pairs.sort()
    return pairs

